INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(46811, 'Exodus 28:10', 'Exodus', 28, 10, 'یعنې د هغوی د عمر په ترتیب، شپږ نومونه په یوه تیږه باندې او پاتې شپږ په بله تیږه باندې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_10.mp3', '', 1761754199, 1761754199),
(46812, 'Exodus 28:11', 'Exodus', 28, 11, 'د یعقوب د زامنو د نومونو نقش په دوو تیږو باندې داسې وباسه لکه څنګه چې د غمي جوړوونکی د یو مهر نقش وباسي. بیا تیږې په هغو ځایونو کې ولګوه چې د سرو زرو د قابونو په شان جوړ شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_11.mp3', '', 1761754199, 1761754199),
(46813, 'Exodus 28:12', 'Exodus', 28, 12, 'هغه تیږې د سپېڅلي پېشبند د اوږې په تسمو باندې ولګوه چې د اسراییلو د دولسو قبیلو استازیتوب وکړي. په دې ډول به هارون د هغوی نومونه په خپلو اوږو باندې انتقالوي، ترڅو زه څښتن تل خپل قوم په یاد وساتم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_12.mp3', '', 1761754199, 1761754199),
(46814, 'Exodus 28:13', 'Exodus', 28, 13, 'د سرو زرو د قابونو په شان دوه ځایونه جوړ کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_13.mp3', '', 1761754199, 1761754199),
(46815, 'Exodus 28:14', 'Exodus', 28, 14, 'او دوه د سوچه سرو زرو تاو شوي زنځیرونه د یوې رسۍ په شان جوړ کړه او په هغو ځایونو کې یې ولګوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_14.mp3', '', 1761754199, 1761754199),
(46816, 'Exodus 28:15', 'Exodus', 28, 15, 'د لوی کاهن دپاره سینه پوښ جوړ کړه چې د خدای د رضا د معلومولو دپاره ورڅخه کار واخلي. هغه دې د هماغو موادو څخه جوړ شي چې سپېڅلی پېشبند ورڅخه جوړ شوی دی او هماغسې ګلدوزي دې په کې وشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_15.mp3', '', 1761754199, 1761754199),
(46817, 'Exodus 28:16', 'Exodus', 28, 16, 'هغه دې څلور کنجه وي، دوه ویشت سانتي دې اوږد وي او دوه ویشت سانتي دې پلن وي او دوه قاته دې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_16.mp3', '', 1761754199, 1761754199),
(46818, 'Exodus 28:17', 'Exodus', 28, 17, 'بیا په هغه باندې څلور قطاره قیمتي تیږې ولګوه. په لومړي قطار کې یو یاقوت، یو زیړ یاقوت او یو لعل ولګوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_17.mp3', '', 1761754199, 1761754199),
(46819, 'Exodus 28:18', 'Exodus', 28, 18, 'په دوهم قطار کې یو زمرد، یوه د لاجوردو تیږه او یو الماس ولګوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_18.mp3', '', 1761754199, 1761754199),
(46820, 'Exodus 28:19', 'Exodus', 28, 19, 'په درېم قطار کې یوه فیروزه، یو سپین عقیق او یو بانجاني یاقوت ولګوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_19.mp3', '', 1761754199, 1761754199),
(46821, 'Exodus 28:20', 'Exodus', 28, 20, 'او په څلورم قطار کې یو شینکی یاقوت، د عقیقو یوه تیږه او یو کوارتز ولګوه. هغه دې په داسې ځایونو کې ولګول شي چې د سرو زرو د قابونو په شان جوړ شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_20.mp3', '', 1761754199, 1761754199),
(46822, 'Exodus 28:21', 'Exodus', 28, 21, 'دولس تیږې دې وي، د یعقوب د زامنو د هر نوم دپاره یوه یوه تیږه. په هرې یوې کې دې د یو مهر په شان نقش وويستل شي او د دولسو قبیلو څخه دې د یوې قبیلې نوم په کې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_21.mp3', '', 1761754199, 1761754199),
(46823, 'Exodus 28:22', 'Exodus', 28, 22, 'د سینه پوښ دپاره د سوچه سرو زرو څخه داسې زنځیرونه جوړ کړه چې د یوې رسۍ په شان تاو شوي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_22.mp3', '', 1761754199, 1761754199),
(46824, 'Exodus 28:23', 'Exodus', 28, 23, 'دوه د سرو زرو کړۍ ګانې جوړې کړه او د سینه پوښ په پورتنیو کنجونو یې ونښلوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_23.mp3', '', 1761754199, 1761754199),
(46825, 'Exodus 28:24', 'Exodus', 28, 24, 'او په دغو دوو کړیو باندې دوه د سرو زرو زنځیرونه وتړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_24.mp3', '', 1761754199, 1761754199),
(46826, 'Exodus 28:25', 'Exodus', 28, 25, 'د زنځیرونو دوه نور سرونه د هغو ځایونو پورې وتړه چې د سرو زرو څخه جوړ شویو قابونو په شان دي او په دې ډول یې د سپېڅلي پېشبند د اوږې د تسمو په مخکینۍ برخې باندې ونښلوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_25.mp3', '', 1761754199, 1761754199),
(46827, 'Exodus 28:26', 'Exodus', 28, 26, 'بیا د سرو زرو دوه کړۍ ګانې جوړې کړه او د سینه پوښ په لاندېنیو کنجونو پورې یې ونښلوه. هغه دې په دنننۍ څنډې باندې د سپېڅلي پېشبند په څنګ کې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_26.mp3', '', 1761754199, 1761754199),
(46828, 'Exodus 28:27', 'Exodus', 28, 27, 'دوه نورې کړۍ ګانې جوړې کړه او د اوږې د تسمو په لاندېنۍ برخه کې یې ونښلوه چې د سپېڅلي پېشبند په مخکینۍ برخې باندې بخۍ ته نژدې او د سپېڅلي پېشبند د کمربند دپاسه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_27.mp3', '', 1761754199, 1761754199),
(46829, 'Exodus 28:28', 'Exodus', 28, 28, 'د سینه پوښ کړۍ ګانې دې د سپېڅلي پېشبند د کړۍ ګانو سره چې د کمربند سره وصل دي په ابي مزي باندې وتړل شي، ترڅو سینه پوښ د سپېڅلي پېشبند څخه لېرې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_28.mp3', '', 1761754199, 1761754199),
(46830, 'Exodus 28:29', 'Exodus', 28, 29, 'هرکله چې هارون سپېڅلي ځای ته ورننوځي، هغه به هغه سینه پوښ اغوندي چې د اسراییلو د قبیلو نومونه ورباندې لیکل شوي دي. هغه به دا نومونه د خپل زړه دپاسه وړي، ترڅو زه څښتن تل خپل قوم رایادوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_29.mp3', '', 1761754199, 1761754199),
(46831, 'Exodus 28:30', 'Exodus', 28, 30, 'اوریم او تمیم په سینه پوښ کې د هغه د زړه دپاسه کېږده. نو کله چې هارون زما پاک حضور ته راځي، هغه به یې وړي. په داسې وختونو کې باید هغه تل دا سینه پوښ واغوندي، ترڅو د اسراییلو د قوم دپاره زما رضا معلومه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_30.mp3', '', 1761754199, 1761754199),
(46832, 'Exodus 28:31', 'Exodus', 28, 31, 'هغه چپنه چې د سپېڅلي پېشبند لاندې اغوستل کیږي، هغه ټوله دې د ابي ټوټې څخه جوړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_31.mp3', '', 1761754199, 1761754199),
(46833, 'Exodus 28:32', 'Exodus', 28, 32, 'د هغې په منځ کې دې د سر دپاره یو سوری پرېښودل شي او د سوري ګردچاپېره دې یوه غاړه وګنډل شي، ترڅو چپنه ونه شلیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_32.mp3', '', 1761754199, 1761754199),
(46834, 'Exodus 28:33', 'Exodus', 28, 33, 'د چپنې د لمنې په څنډه باندې د ابي، بانجاني او سرو وړیو څخه داسې انار جوړ کړه چې په منځ کې یې د سرو زرو زنګونه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_33.mp3', '', 1761754199, 1761754199),
(46835, 'Exodus 28:34', 'Exodus', 28, 34, 'د سرو زرو زنګونه او انار دې د چپنې د لمنې ګردچاپېره د یو بل ترمنځ راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_34.mp3', '', 1761754199, 1761754199),
(46836, 'Exodus 28:35', 'Exodus', 28, 35, 'هارون دې د کاهن په توګه د خدمت کولو په وخت کې دغه چپنه واغوندي. کله چې هغه زما حضور ته په سپېڅلي ځای کې راننوځي یا کله چې هغه ځي، د زنګونو اواز به اورېدل کیږي او هغه به نه وژل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_35.mp3', '', 1761754199, 1761754199),
(46837, 'Exodus 28:36', 'Exodus', 28, 36, 'د سوچه سرو زرو څخه یو ګل جوړ کړه او په هغه باندې د دې لغتونو یعنې ‹څښتن ته وقف شوی› یو نقش وباسه لکه څنګه چې په یو مهر باندې ویستل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_36.mp3', '', 1761754199, 1761754199),
(46838, 'Exodus 28:37', 'Exodus', 28, 37, 'هغه ګل په یو ابي مزي باندې د لونګۍ په مخکینۍ برخې پورې وتړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_37.mp3', '', 1761754199, 1761754199),
(46839, 'Exodus 28:38', 'Exodus', 28, 38, 'هارون دې هغه په خپل تندي باندې وتړي، ترڅو زه څښتن هغه ټولې سپېڅلې نذرانې چې اسراییلیان یې ماته وقف کوي قبولې کړم، حتی که چېرې خلک د هغو په وړاندې کولو کې کومه سهوه هم وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_38.mp3', '', 1761754199, 1761754199),
(46840, 'Exodus 28:39', 'Exodus', 28, 39, 'د هارون دپاره د ښه کتان څخه کمیس او یوه لونګۍ جوړ کړه. پټۍ هم جوړه کړه او هغه دې ګلدوزي شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_39.mp3', '', 1761754199, 1761754199),
(46841, 'Exodus 28:40', 'Exodus', 28, 40, 'د هارون د زامنو دپاره کمیسونه، پټۍ ګانې او خولۍ ګانې جوړې کړه چې هغوی ته عزت او ښکلا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_40.mp3', '', 1761754199, 1761754199),
(46842, 'Exodus 28:41', 'Exodus', 28, 41, 'خپل ورور هارون او د هغه زامنو ته دغه کالي ورواغونده. هغوی د زیتون په تېلو باندې مسح کړه او مقرر یې کړه. هغوی وقف کړه، ترڅو د کاهنانو په توګه زما خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_41.mp3', '', 1761754199, 1761754199),
(46843, 'Exodus 28:42', 'Exodus', 28, 42, 'د هغوی دپاره د کتان داسې نېکرونه جوړ کړه چې د ملا څخه نیولې تر ورنونو پورې ورسیږي چې بدنونه یې ښکاره نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_42.mp3', '', 1761754199, 1761754199),
(46844, 'Exodus 28:43', 'Exodus', 28, 43, 'کله چې هارون او د هغه زامن سپېڅلې خېمې ته ورننوځي یا د قربانۍ ځای ته ورنژدې کیږي چې په سپېڅلي ځای کې د کاهنانو په توګه خدمت وکړي، باید تل هغه واغوندي ترڅو هغوی خپل ځانونه ګناهکار نه کړي او مړه نه شي. دا دې د هارون او د هغه د اولادې دپاره یو تلپاتې حکم وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus28_verse_43.mp3', '', 1761754199, 1761754199),
(46845, 'Psalms 21:1', 'Psalms', 21, 1, 'پاچا ستا په طاقت کوي څښتنه خوشحالي کړي څومره لویه خوشحالي ځکه چې تا ورته بری ورکړی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_1.mp3', '', 1761754199, 1761754199),
(46846, 'Psalms 21:2', 'Psalms', 21, 2, 'تا دی پوره کړی د هغه د زړه ارمان رد کړی نه دی تا د هغه د خولې سوال', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_2.mp3', '', 1761754199, 1761754199),
(46847, 'Psalms 21:3', 'Psalms', 21, 3, 'تا پاچا کړ استقبال په ډېرو ښو برکتونو کېښود دې په سر د هغه تاج د سوچه سرو زرو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_3.mp3', '', 1761754199, 1761754199),
(46848, 'Psalms 21:4', 'Psalms', 21, 4, 'هغه ژوند وغوښت له تا نه اوږد عمر دوامدار دې ورته ورکړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_4.mp3', '', 1761754199, 1761754199),
(46849, 'Psalms 21:5', 'Psalms', 21, 5, 'ستا په مرسته د هغه جلال ډېر لوی شو تا ورکړی دی هغه ته ښه شهرت هم ډېر زیات شان او شوکت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_5.mp3', '', 1761754199, 1761754199),
(46850, 'Psalms 21:6', 'Psalms', 21, 6, 'هغه ته دې ورکړی برکت نه‌ختمېدونکی دی ورکړی خپل دیدار دې ورته زړه خوشحالوونکی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_6.mp3', '', 1761754199, 1761754199),
(46851, 'Psalms 21:7', 'Psalms', 21, 7, 'کړي پاچا توکل څښتن تعالی باندې په سبب د ده د تلپاتې مینې هغه تل به وي په امن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_7.mp3', '', 1761754199, 1761754199),
(46852, 'Psalms 21:8', 'Psalms', 21, 8, 'ته به خپل ټول دښمنان ونیسې وبه نیسې هغو چې کوي کرکه له تا نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_8.mp3', '', 1761754199, 1761754199),
(46853, 'Psalms 21:9', 'Psalms', 21, 9, 'چې ښکاره کله ته ځان کړې د تنور د اور په شان به دوی برباد کړې په خپل قهر به څښتن هغوی هلاک کړي دوی به وسوځوي اور', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_9.mp3', '', 1761754199, 1761754199),
(46854, 'Psalms 21:10', 'Psalms', 21, 10, 'ته به مړه کړې هغوی ټول څوک ژوندی به پاتې نه شي د هغوی د اولادې نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_10.mp3', '', 1761754199, 1761754199),
(46855, 'Psalms 21:11', 'Psalms', 21, 11, 'جوړوي د ستا په ضد دوی دسیسې او ستا په ضد د شرارت پلانونه خو کامیاب به دوی پرې نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_11.mp3', '', 1761754199, 1761754199),
(46856, 'Psalms 21:12', 'Psalms', 21, 12, 'په هغوی باندې به خپل غشي ګوزار کړې دوی په شا به شي او وبه کاندي تېښته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_12.mp3', '', 1761754199, 1761754199),
(46857, 'Psalms 21:13', 'Psalms', 21, 13, 'مونږه ستا کوو ستاینه ای څښتنه ستا د لوی قوت دپاره مونږ به ووایو سندرې او ثنا ستا د قدرت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms21_verse_13.mp3', '', 1761754199, 1761754199),
(46858, 'Proverbs 15:1', 'Proverbs', 15, 1, 'نرم ځواب د غوسې اور سړوي خو سخته خبره سمدلاسه د قهر لمبې پورته کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_1.mp3', '', 1761754199, 1761754199),
(46859, 'Proverbs 15:2', 'Proverbs', 15, 2, 'د هوښیارانو ژبه علم ته ښایست ورکوي خو د کم‌عقلانو له خولې نه جهالت توییږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_2.mp3', '', 1761754199, 1761754199),
(46860, 'Proverbs 15:3', 'Proverbs', 15, 3, 'هرځای د څښتن تر نظر لاندې دی او په ښو او بدو باندې ټینګ پام ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_3.mp3', '', 1761754199, 1761754199),
(46861, 'Proverbs 15:4', 'Proverbs', 15, 4, 'نرمه ژبه د ژوندانه د ونې په څېر ده خو سخته ژبه زړه ماتوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_4.mp3', '', 1761754199, 1761754199),
(46862, 'Proverbs 15:5', 'Proverbs', 15, 5, 'جاهل انسان د خپل پلار نصیحت سپک ګڼي خو ځیرک سړی تل ملامتیا مني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_5.mp3', '', 1761754199, 1761754199),
(46863, 'Proverbs 15:6', 'Proverbs', 15, 6, 'د نېک سړي په کور کې لویه خزانه وي خو د بدکاره شتمني د تکلیف سبب ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_6.mp3', '', 1761754199, 1761754199),
(46864, 'Proverbs 15:7', 'Proverbs', 15, 7, 'علم د هوښیارانو په خوله خپریږي خو د کم‌عقلانو په زړونو کې رښتینولي نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_7.mp3', '', 1761754199, 1761754199),
(46865, 'Proverbs 15:8', 'Proverbs', 15, 8, 'څښتن د بدکارانو له قربانۍ نه کرکه کوي خو د صادقانو په دعا خوشحالیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_8.mp3', '', 1761754199, 1761754199),
(46866, 'Proverbs 15:9', 'Proverbs', 15, 9, 'څښتن د بدکارانو له چلند نه کرکه کوي خو څوک چې په صداقت پسې روان وي ورسره مینه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_9.mp3', '', 1761754199, 1761754199),
(46867, 'Proverbs 15:10', 'Proverbs', 15, 10, 'د سمې لار نه مخ اړوونکی به له سختې سزا سره مخامخ شي او څوک چې له ملامتیا او رټنې نه کرکه کوي نو هغه به مړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_10.mp3', '', 1761754199, 1761754199),
(46868, 'Proverbs 15:11', 'Proverbs', 15, 11, 'څښتن ته قبر او د تباهۍ کنده دواړه ښکاري نو د انسانانو زړونه به ورته څومره ښکاره وي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_11.mp3', '', 1761754199, 1761754199),
(46869, 'Proverbs 15:12', 'Proverbs', 15, 12, 'ملنډې وهونکی اصلاح نه خوښوي او د هوښیارانو له مشورې نه ځان لېرې ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_12.mp3', '', 1761754199, 1761754199),
(46870, 'Proverbs 15:13', 'Proverbs', 15, 13, 'خوشحاله زړه مخ نوراني کوي خو پرېشانه زړه روح ماتوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_13.mp3', '', 1761754199, 1761754199),
(46871, 'Proverbs 15:14', 'Proverbs', 15, 14, 'عقلمن انسان د علم تږی وي خو کم‌عقل د جهالت وږی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_14.mp3', '', 1761754199, 1761754199),
(46872, 'Proverbs 15:15', 'Proverbs', 15, 15, 'د مظلومانو د ژوند ټولې ورځې سختې وي خو خوشحاله زړه هر وخت له ژوند نه خوند اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_15.mp3', '', 1761754199, 1761754199),
(46873, 'Proverbs 15:16', 'Proverbs', 15, 16, 'د څښتن له وېرې سره لږه شتمني ښه ده له هغو ډېرو خزانو نه چې ورسره وېره او اندېښنه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_16.mp3', '', 1761754199, 1761754199),
(46874, 'Proverbs 15:17', 'Proverbs', 15, 17, 'له مینې سره سابه او سوکړک خوړل ښه دي د هغې غوړې غوښې نه چې ورسره کرکه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_17.mp3', '', 1761754199, 1761754199),
(46875, 'Proverbs 15:18', 'Proverbs', 15, 18, 'غوسه ناک سړی جنجال جوړوي خو څوک چې زر نه په قهریږي شخړې سړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_18.mp3', '', 1761754199, 1761754199),
(46876, 'Proverbs 15:19', 'Proverbs', 15, 19, 'د لټ سړي په لار کې د اغزو ډکه حوېلۍ وي خو د صادقانو لاره د پوخ سرک په شان هواره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_19.mp3', '', 1761754199, 1761754199),
(46877, 'Proverbs 15:20', 'Proverbs', 15, 20, 'هوښیار زوی خپل پلار خوشحالوي خو کم‌عقل سړی د خپلې مور سپکاوی کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_20.mp3', '', 1761754199, 1761754199),
(46878, 'Proverbs 15:21', 'Proverbs', 15, 21, 'ناپوهه انسان له جهالت نه خوند اخلي خو د پوهې خاوند په سمه لار روان وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_21.mp3', '', 1761754199, 1761754199),
(46879, 'Proverbs 15:22', 'Proverbs', 15, 22, 'له مشورې پرته ټولې نقشې شنډیږي خو له ډېرو مشوره ورکوونکو سره بریالې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_22.mp3', '', 1761754199, 1761754199),
(46880, 'Proverbs 15:23', 'Proverbs', 15, 23, 'انسان په مناسب ځواب ورکولو خوشحالیږي نو په مناسب وخت کې سمه خبره کول څومره ښه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_23.mp3', '', 1761754199, 1761754199),
(46881, 'Proverbs 15:24', 'Proverbs', 15, 24, 'د هوښیارانو لار انسان تلپاتې ژوند ته بیایي او هغه د قبر په لور د لاندې تګ نه ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_24.mp3', '', 1761754199, 1761754199),
(46882, 'Proverbs 15:25', 'Proverbs', 15, 25, 'څښتن د کبرجنو کور ورانوي خو د کونډې د جایداد پوله ټینګه ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_25.mp3', '', 1761754199, 1761754199),
(46883, 'Proverbs 15:26', 'Proverbs', 15, 26, 'څښتن د بدکارانو له فکرونو نه کرکه کوي خو مهربانې خبرې پاکې ګڼي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_26.mp3', '', 1761754199, 1761754199),
(46884, 'Proverbs 15:27', 'Proverbs', 15, 27, 'څوک چې په ناروا ګټې پسې ګرځي خپلې کورنۍ ته مصیبت رسوي خو څوک چې له رشوت نه کرکه کوي هغوی به ژوندي پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_27.mp3', '', 1761754199, 1761754199),
(46885, 'Proverbs 15:28', 'Proverbs', 15, 28, 'نېک سړی له ځواب ورکولو نه مخکې فکر کوي خو د بدکارانو له خولې نه بدې خبرې راوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_28.mp3', '', 1761754199, 1761754199),
(46886, 'Proverbs 15:29', 'Proverbs', 15, 29, 'څښتن له بدکارانو نه لېرې دی خو د نېکانو دعاګانې تل اوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_29.mp3', '', 1761754199, 1761754199),
(46887, 'Proverbs 15:30', 'Proverbs', 15, 30, 'په ورین تندي کتل زړه ته خوشحالي ورکوي او د ښې خبرې اورېدل بدن تازه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_30.mp3', '', 1761754199, 1761754199),
(46888, 'Proverbs 15:31', 'Proverbs', 15, 31, 'څوک چې جوړوونکې نیوکې ته غوږ نیسي نو د هوښیارانو په ډله کې شمېرل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_31.mp3', '', 1761754199, 1761754199),
(46889, 'Proverbs 15:32', 'Proverbs', 15, 32, 'څوک چې له نصیحت نه ډډه کوي خپل ځان سپکوي خو څوک چې ملامتیا مني نو عقل او پوهه حاصلوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_32.mp3', '', 1761754199, 1761754199),
(46890, 'Proverbs 15:33', 'Proverbs', 15, 33, 'له څښتن څخه وېره انسان ته د حکمت ډک نصیحت دی او عاجزي د سرلوړۍ سبب ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs15_verse_33.mp3', '', 1761754199, 1761754199),
(46891, 'Proverbs 22:1', 'Proverbs', 22, 1, 'نېک نامي د ډېرې شتمنۍ نه غوره ده او عزت د سرو او سپینو زرو نه بهتر دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_1.mp3', '', 1761754199, 1761754199),
(46892, 'Proverbs 22:2', 'Proverbs', 22, 2, 'شتمن او غریب په یو صفت کې شریک دي ځکه چې څښتن د دواړو خالق دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_2.mp3', '', 1761754199, 1761754199),
(46893, 'Proverbs 22:3', 'Proverbs', 22, 3, 'ځیرک انسان بدي او بلا ویني او خپل ځان ترې ساتي خو ساده سړی د هغې په لور روان وي او سزا به یې ویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_3.mp3', '', 1761754199, 1761754199),
(46894, 'Proverbs 22:4', 'Proverbs', 22, 4, 'عاجزي د څښتن له وېرې پیدا کیږي چې انسان ته شتمني، عزت او نېکمرغه ژوند ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_4.mp3', '', 1761754199, 1761754199),
(46895, 'Proverbs 22:5', 'Proverbs', 22, 5, 'د دروغجن انسان لار له اغزو او دامونو نه ډکه وي خو په چا چې خپل ځان ګران وي نو ځان ترې لېرې ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_5.mp3', '', 1761754199, 1761754199),
(46896, 'Proverbs 22:6', 'Proverbs', 22, 6, 'ماشوم په سمه لار روان کړه. که سپین‌ږیری هم شي نو مخ به ترې وانه ړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_6.mp3', '', 1761754199, 1761754199),
(46897, 'Proverbs 22:7', 'Proverbs', 22, 7, 'شتمن په مسکینانو باندې حکومت کوي او پور اخیستونکی د پور ورکوونکي غلام دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_7.mp3', '', 1761754199, 1761754199),
(46898, 'Proverbs 22:8', 'Proverbs', 22, 8, 'څوک چې د بې‌انصافۍ تخم کري نو مصیبت به رېبي او د کبر کاسه به یې نسکوره شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_8.mp3', '', 1761754199, 1761754199),
(46899, 'Proverbs 22:9', 'Proverbs', 22, 9, 'بختور دی هغه څوک چې سخاوت کوي ځکه د خپلو خوړو یوه برخه خوارانو ته ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_9.mp3', '', 1761754199, 1761754199),
(46900, 'Proverbs 22:10', 'Proverbs', 22, 10, 'ملنډې وهونکی وشړه نو شخړې به ورسره ختم شي بحثونه او پېغورونه به ورسره هم بند شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_10.mp3', '', 1761754199, 1761754199),
(46901, 'Proverbs 22:11', 'Proverbs', 22, 11, 'څوک چې د پاک زړه خاوند وي او خوږې خبرې کوي نو پاچا به هم د هغه ملګری شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_11.mp3', '', 1761754199, 1761754199),
(46902, 'Proverbs 22:12', 'Proverbs', 22, 12, 'څښتن په علم او پوهه خپل نظر ساتي خو د خاینانو نقشې له منځه وړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_12.mp3', '', 1761754199, 1761754199),
(46903, 'Proverbs 22:13', 'Proverbs', 22, 13, 'لټ سړی له کور څخه نه وځي او وایي: «بهر زمری دی! که کوڅې ته ووځم نو مړ به مې کړي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_13.mp3', '', 1761754199, 1761754199),
(46904, 'Proverbs 22:14', 'Proverbs', 22, 14, 'د زناکارې ښځې خوله د ژورې کندې په څېر ده چاته چې څښتن په غوسه وي نو په کې غورځیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_14.mp3', '', 1761754199, 1761754199),
(46905, 'Proverbs 22:15', 'Proverbs', 22, 15, 'جهالت د ماشوم په زړه کې نغښتی وي خو د ادب لښته به یې ترې لېرې وباسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_15.mp3', '', 1761754199, 1761754199),
(46906, 'Proverbs 22:16', 'Proverbs', 22, 16, 'څوک چې په غریب ظلم وکړي او خپله شتمني ډېره کړي او شتمن ته تحفې ورکوي، نو اخر به نېستمن شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_16.mp3', '', 1761754199, 1761754199),
(46907, 'Proverbs 22:17', 'Proverbs', 22, 17, 'د حکمت د خاوندانو خبرو ته غوږ نیسه او ورته پام کوه او زما تعلیم د زړه له کومي قبول کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_17.mp3', '', 1761754199, 1761754199),
(46908, 'Proverbs 22:18', 'Proverbs', 22, 18, 'نو که دا خبرې د زړه په تل کې وساتې او تل ستا په شونډو وي نو خوشحالي به دې په برخه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_18.mp3', '', 1761754199, 1761754199),
(46909, 'Proverbs 22:19', 'Proverbs', 22, 19, 'نو زه همدا نن تاته تعلیم درکوم د دې دپاره چې په څښتن باندې پوره باور ولرې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_19.mp3', '', 1761754199, 1761754199),
(46910, 'Proverbs 22:20', 'Proverbs', 22, 20, 'ما ستا دپاره دېرش نصیحتونه لیکلي دي چې د علم او نصیحت نه ډک دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs22_verse_20.mp3', '', 1761754199, 1761754199);